cd /app && echo '=== ZIP signatures in image ==='; grep -abo -E 'PK\x03\x04|PK\x01\x02|PK\x05\x06' /app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat | head -20; echo; echo '=== CRC32 verify with perl ==='; perl -e '
my @t;
for my $n (0..255) { my $c=$n; for (1..8){ $c = ($c&1) ? (0xEDB88320 ^ ($c>>1)) : ($c>>1); } $t[$n]=$c; }
sub crc32 { my $d=shift; my $c=0xFFFFFFFF; for my $b (unpack("C*",$d)) { $c = $t[($c ^ $b) & 0xFF] ^ ($c>>8); } return $c ^ 0xFFFFFFFF; }
my $line = "PASSWORD=8XDP5Q2RT9ZK7VB3BV4WW54\n";
my $pw = "8XDP5Q2RT9ZK7VB3BV4WW54";
printf "password len: %d\n", length($pw);
printf "file len: %d (zip header says %d)\n", length($line), 0x21;
printf "computed crc32: 0x%08x\n", crc32($line);
printf "expected crc32: 0xb0725dc4\n";
my $ok = (length($pw)==23 && $pw=~/^8XD[A-Z0-9]{17}W54$/ && crc32($line)==0xb0725dc4);
printf "VERDICT: %s\n", $ok ? "MATCH - candidate verified" : "MISMATCH";
exit($ok?0:1);
'

